UPDATE Candidato SET
  cpf = COALESCE(NULLIF(cpf, ''), (
    SELECT NULLIF(t.cpf, '') FROM tmp_cpf26 t
    JOIN Cargo c ON c.id = Candidato.cargoId JOIN Eleicao e ON c.eleicaoId = e.id
    WHERE e.ano = 2026 AND t.cargo = c.nome AND t.numero = Candidato.numero
      AND UPPER(t.nomeUrna) = UPPER(Candidato.nome)
  )),
  nomeCompleto = COALESCE(NULLIF(nomeCompleto, ''), (
    SELECT t.nomeCivil FROM tmp_cpf26 t
    JOIN Cargo c ON c.id = Candidato.cargoId JOIN Eleicao e ON c.eleicaoId = e.id
    WHERE e.ano = 2026 AND t.cargo = c.nome AND t.numero = Candidato.numero
      AND UPPER(t.nomeUrna) = UPPER(Candidato.nome)
  ))
WHERE id IN (
  SELECT ca.id FROM Candidato ca JOIN Cargo c ON ca.cargoId = c.id JOIN Eleicao e ON c.eleicaoId = e.id
  WHERE e.ano = 2026 AND c.nome IN ('Governador','Senador','Deputado Federal','Deputado Estadual')
);

UPDATE Candidato SET
  cpf = COALESCE(NULLIF(cpf, ''), (
    SELECT NULLIF(t.cpf, '') FROM tmp_cpf26fb t
    JOIN Cargo c ON c.id = Candidato.cargoId JOIN Eleicao e ON c.eleicaoId = e.id
    WHERE e.ano = 2026 AND t.cargo = c.nome AND t.numero = Candidato.numero
  )),
  nomeCompleto = COALESCE(NULLIF(nomeCompleto, ''), (
    SELECT t.nomeCivil FROM tmp_cpf26fb t
    JOIN Cargo c ON c.id = Candidato.cargoId JOIN Eleicao e ON c.eleicaoId = e.id
    WHERE e.ano = 2026 AND t.cargo = c.nome AND t.numero = Candidato.numero
  ))
WHERE id IN (
  SELECT ca.id FROM Candidato ca JOIN Cargo c ON ca.cargoId = c.id JOIN Eleicao e ON c.eleicaoId = e.id
  WHERE e.ano = 2026 AND c.nome IN ('Governador','Senador','Deputado Federal','Deputado Estadual')
);

